//! Pyrealium's AC2 Vault quests (`quest-*-vault.tsv`, `emote-*-vault.tsv`, generated by Pyrealium's
//! `tools/import_vault_quests.py`) against a running Pyrealium (`PYREALIUM_LIVE`, see `tests/live/mod.rs`),
//! played as a player does: the NPC's offer (its DAT line), the journal's phases (the DAT quest
//! table's lines), the kills or the talks, the reward line and experience, and the refusal after.
//! Every line the client receives is printed (`VAULT ...`), the record of the live check.
//!
//! Run with `PYREALIUM_LIVE_TEST=pyrealium_live_vault scripts/pyrealium-live-test.sh`. The script's profile for
//! this file gives the new character experience (`PYREALIUM_DEV_START_XP`), caps creature health
//! (`PYREALIUM_DEV_CREATURE_HEALTH`, Pyrealium's test-server knob: a new character hits a Carrion Shreth
//! for 2 of its 380) and places four more of each hunt's creatures beside the landing point
//! (`PYREALIUM_EXTRA_WORLD`): the world holds one Green Phyntos Wasp point, and the Carrion Shreth's is
//! out of reach of it. Each test runs on a server of its own.

#![cfg(feature = "window")]

mod live;

use ac2_client::Command;
use ac2_ui::ToolbarChild;
use ac2_weenie::{GameplayNotice, SessionEvent};
use live::LiveRig;

fn notices(rig: &LiveRig, from: usize) -> Vec<(u32, u32, Option<String>)> {
    rig.seen[from..]
        .iter()
        .filter_map(|e| match e {
            SessionEvent::Notice(GameplayNotice::DisplayStringInfo { text, .. })
            | SessionEvent::Notice(GameplayNotice::DisplayMessage { text, .. }) => {
                Some((text.table_id, text.string_id, text.literal.clone()))
            }
            _ => None,
        })
        .collect()
}
fn said(rig: &LiveRig, from: usize, line: (u32, u32)) -> bool {
    notices(rig, from).iter().any(|n| (n.0, n.1) == line)
}
/// Logs what the client received since `from` (the live check's record).
fn log(rig: &LiveRig, step: &str, from: usize) {
    for (table, key, literal) in notices(rig, from) {
        eprintln!(
            "VAULT {step}: {table:08x}/{key:08x} {}",
            literal.unwrap_or_default()
        );
    }
    let (u, f) = rig.view.quest_journal_texts();
    eprintln!("VAULT {step}: journal underway {:?} finished {:?}", u, f);
}
fn journal(rig: &LiveRig) -> (String, String) {
    let (u, f) = rig.view.quest_journal_texts();
    (u.join(" | "), f.join(" | "))
}
fn experience(rig: &LiveRig) -> u64 {
    rig.client.frame().progress.experience.total_xp
}
fn travel(rig: &mut LiveRig, x: f64, y: f64, again: bool) {
    if again {
        rig.relog();
        rig.panel(ToolbarChild::Quest, true);
    }
    let cell = rig.client.frame().player.as_ref().map(|p| p.cell);
    rig.command(Command::Say(format!("@maptravel {x:.2} {y:.2}")));
    assert!(
        rig.until(30.0, |r| {
            let frame = r.client.frame();
            frame.in_world && frame.player.as_ref().map(|p| p.cell) != cell
        }),
        "the map travel to {x} {y} did not take the player away"
    );
    rig.run(3.0);
}
fn npc(rig: &mut LiveRig, entity: u32) -> u64 {
    rig.wait("the NPC", |r| {
        r.object_of(entity).is_some_and(|n| r.place_of(n).is_some())
    });
    let id = rig.object_of(entity).unwrap();
    rig.run(1.0);
    id
}
fn talk(rig: &mut LiveRig, id: u64) -> usize {
    let from = rig.seen.len();
    rig.command(Command::Use(id));
    rig.run(3.0);
    from
}
fn alive_of(rig: &LiveRig, id: u64, entity: u32) -> bool {
    rig.client.session().objects().get(id).is_some_and(|o| {
        o.entity == Some(entity) && o.qualities.inq_int(0x14).is_some_and(|t| t & 0x4F == 0x4F)
    })
}
fn nearest(rig: &LiveRig, entity: u32, fought: &[u64]) -> Option<u64> {
    let frame = rig.client.frame();
    let me = frame.player.as_ref()?;
    frame
        .objects
        .iter()
        .filter(|o| o.in_world && !fought.contains(&o.id) && alive_of(rig, o.id, entity))
        .map(|o| {
            (
                o.id,
                (o.origin[0] - me.origin[0]).hypot(o.origin[1] - me.origin[1]),
            )
        })
        .filter(|&(_, d)| d < 60.0)
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .map(|(id, _)| id)
}
fn kill(rig: &mut LiveRig, target: u64) -> bool {
    let before = rig.seen.len();
    let fallen = |r: &LiveRig| {
        notices(r, before)
            .iter()
            .any(|n| n.2.as_deref().is_some_and(|l| l.contains("defeated")))
            || r.client
                .session()
                .objects()
                .get(target)
                .is_none_or(|x| x.qualities.inq_int(0x102).is_some_and(|h| h <= 0))
    };
    rig.command(Command::Select(Some(target)));
    rig.run(0.5);
    let mut dead = false;
    for _ in 0..6 {
        rig.command(Command::SetAttacking(true));
        rig.until(15.0, |r| fallen(r));
        dead = fallen(rig);
        if dead {
            break;
        }
        rig.command(Command::SetAttacking(false));
        rig.run(0.5);
    }
    rig.command(Command::SetAttacking(false));
    rig.run(1.0);
    let said: Vec<String> = notices(rig, before)
        .into_iter()
        .map(|n| n.2.unwrap_or_else(|| format!("{:08x}/{:08x}", n.0, n.1)))
        .collect();
    eprintln!("VAULT fight {target:x} dead {dead}: {said:?}");
    dead
}

struct Hunt {
    name: &'static str,
    npc: u32,
    /// Land point 2 m from the NPC, and where the creatures stand.
    at_npc: (f64, f64),
    at_prey: (f64, f64),
    prey: u32,
    kills: u32,
    title: &'static str,
    /// The NPC table's offer, 'not done yet', reward and 'no task today' lines.
    offer: (u32, u32),
    busy: (u32, u32),
    reward: (u32, u32),
    no_task: (u32, u32),
    /// The journal's phase lines: the first and the report line.
    first_phase: &'static str,
    report: &'static str,
    xp: u64,
}

fn play(h: Hunt) {
    let Some(mut rig) = LiveRig::new(h.name) else {
        return;
    };
    rig.panel(ToolbarChild::Quest, true);
    // The offer: the NPC's DAT line, the journal's entry at its first phase.
    travel(&mut rig, h.at_npc.0, h.at_npc.1, false);
    let giver = npc(&mut rig, h.npc);
    let from = talk(&mut rig, giver);
    log(&rig, "offer", from);
    assert!(said(&rig, from, h.offer), "{:?}", notices(&rig, from));
    assert!(
        rig.until(10.0, |r| journal(r).0.contains(h.title)),
        "{:?}",
        journal(&rig)
    );
    assert!(
        journal(&rig).0.contains(h.first_phase),
        "{:?}",
        journal(&rig)
    );
    // Talking again before the kills: the 'not done yet' line, nothing else.
    let from = talk(&mut rig, giver);
    log(&rig, "busy", from);
    assert!(said(&rig, from, h.busy), "{:?}", notices(&rig, from));
    // The kills: each advances the journal; after the last it says to report.
    travel(&mut rig, h.at_prey.0, h.at_prey.1, true);
    let mark = rig.seen.len();
    let mut fought = Vec::new();
    let mut counted = 0;
    while counted < h.kills {
        assert!(
            rig.until(240.0, |r| nearest(r, h.prey, &fought).is_some()),
            "no prey after {counted} kills"
        );
        let target = nearest(&rig, h.prey, &fought).unwrap();
        fought.push(target);
        if kill(&mut rig, target) {
            counted += 1;
            eprintln!("VAULT kill {counted}: {:?}", journal(&rig).0);
        }
    }
    log(&rig, "kills", mark);
    assert!(
        rig.until(10.0, |r| journal(r).0.contains(h.report)),
        "{:?}",
        journal(&rig)
    );
    // The reward: the NPC's reward line and the Vault's experience; the entry is finished.
    travel(&mut rig, h.at_npc.0, h.at_npc.1, true);
    let giver = npc(&mut rig, h.npc);
    let xp = experience(&rig);
    let from = talk(&mut rig, giver);
    log(&rig, "reward", from);
    assert!(said(&rig, from, h.reward), "{:?}", notices(&rig, from));
    assert!(
        rig.until(10.0, |r| experience(r) == xp + h.xp),
        "{} -> {}",
        xp,
        experience(&rig)
    );
    assert!(
        rig.until(10.0, |r| journal(r).1.contains(h.title)),
        "{:?}",
        journal(&rig)
    );
    // Within the seven days: the NPC has no task.
    let from = talk(&mut rig, giver);
    log(&rig, "again", from);
    assert!(said(&rig, from, h.no_task), "{:?}", notices(&rig, from));
}

/// Put Down the Carrion Shreth (AC2 Vault 183): Oriona in Arwic, five Carrion Shreth south of
/// it, 150 experience.
#[test]
fn oriona_s_carrion_shreth_hunt() {
    const T: u32 = 0x2500_8B11; // ard_oriona.stt
    play(Hunt {
        name: "Vault Shreth",
        npc: 0x4700_42EA,
        at_npc: (958.82, 1462.89),
        at_prey: (956.87, 1328.75),
        prey: 0x4700_0F8B,
        kills: 5,
        title: "Put down the Carrion Shreth",
        offer: (T, 0x2AE6_124E),
        busy: (T, 0xCDEB_1FB2),
        reward: (T, 0x68A0_4D4D),
        no_task: (T, 0x0920_0EFE),
        first_phase: "5 Carrion Shreth",
        report: "Report to Oriona.",
        xp: 150,
    });
}

/// Exterminate the Green Phyntos Wasps (AC2 Vault 181): Krestovmik in Arwic, five Green Phyntos
/// Wasps, 120 experience.
#[test]
fn krestovmik_s_green_wasp_hunt() {
    const T: u32 = 0x2500_8B14; // arc_krestovmik.stt
    play(Hunt {
        name: "Vault Wasps",
        npc: 0x4700_42F0,
        at_npc: (957.44, 1462.15),
        at_prey: (1047.0, 1399.46),
        prey: 0x4700_0F9C,
        kills: 5,
        title: "Exterminate the Green Phyntos Wasps",
        offer: (T, 0x2AE6_124E),
        busy: (T, 0xCDEB_1FB2),
        reward: (T, 0x68A0_4D4D),
        no_task: (T, 0x0920_0EFE),
        first_phase: "5 Green Phyntos Wasps",
        report: "Report to Krestovmik.",
        xp: 120,
    });
}

/// Journey to Linvak (AC2 Vault 64), a talk chain: Akkilea in Zu offers it, Pelloran in Whitebay
/// and Kanten in Cavendo say their lines in turn (each line the Vault quotes, from the speaker's
/// own DAT table), and Akkilea pays 10,000 experience; the journal shows the quest table's
/// "Seek out ..." and "Return to Akkilea." lines.
#[test]
fn akkilea_s_journey_to_linvak() {
    const AKKILEA: u32 = 0x4700_1A98;
    const PELLORAN: u32 = 0x4700_1C29;
    const KANTEN: u32 = 0x4700_1A3C;
    let Some(mut rig) = LiveRig::new("Vault Linvak") else {
        return;
    };
    rig.panel(ToolbarChild::Quest, true);
    travel(&mut rig, 1774.03, 1190.65, false);
    let akkilea = npc(&mut rig, AKKILEA);
    let from = talk(&mut rig, akkilea);
    log(&rig, "offer", from);
    assert!(
        said(&rig, from, (0x2500_6FF9, 0x8390_9CDB)),
        "{:?}",
        notices(&rig, from)
    );
    assert!(
        rig.until(10.0, |r| journal(r)
            .0
            .contains("Seek out the Factotum of Whitebay.")),
        "{:?}",
        journal(&rig)
    );
    for (name, at, entity, line, next) in [
        (
            "Pelloran",
            (973.38, 800.46),
            PELLORAN,
            (0x2500_707B, 0x8F8D_CA2A),
            "Seek out the Factotum of Cavendo.",
        ),
        (
            "Kanten",
            (1310.57, 1185.38),
            KANTEN,
            (0x2500_6F84, 0x8F8D_CA2A),
            "Return to Akkilea.",
        ),
    ] {
        travel(&mut rig, at.0, at.1, true);
        let id = npc(&mut rig, entity);
        let from = talk(&mut rig, id);
        log(&rig, name, from);
        assert!(said(&rig, from, line), "{name}: {:?}", notices(&rig, from));
        assert!(
            rig.until(10.0, |r| journal(r).0.contains(next)),
            "{name}: {:?}",
            journal(&rig)
        );
    }
    travel(&mut rig, 1774.03, 1190.65, true);
    let akkilea = npc(&mut rig, AKKILEA);
    let xp = experience(&rig);
    let from = talk(&mut rig, akkilea);
    log(&rig, "reward", from);
    assert!(
        said(&rig, from, (0x2500_6FF9, 0x31AF_023B)),
        "{:?}",
        notices(&rig, from)
    );
    assert!(
        rig.until(10.0, |r| experience(r) == xp + 10_000),
        "{} -> {}",
        xp,
        experience(&rig)
    );
    assert!(
        rig.until(10.0, |r| journal(r).1.contains("Journey To Linvak")),
        "{:?}",
        journal(&rig)
    );
}
